-- 33629208 English: %s {{!is|is not}} auto-repeating
-- %s #1: %s #1: a clickable spell link, e.g. "[Fireball]"
[3653] = "%s {{!se está repitiendo automáticamente|no se está repitiendo automáticamente}}",
-- 9544d41a English: Tests whether the selected spell is currently auto-repeating, such as Shoot or
--     Auto Shot. This is different from a spell being current or queued: a queued cast alone does
--     not satisfy this condition. Unavailable client observations remain unavailable even when
--     negated.
[3654] = "Comprueba si el hechizo seleccionado se está repitiendo automáticamente, como Disparar o Disparo automático. No es lo mismo que un hechizo actual o en cola: un lanzamiento en cola por sí solo no cumple esta condición. Las observaciones del cliente no disponibles siguen sin estar disponibles aunque se nieguen.",
-- 32d5dd3a English: Uses readable positions in the same instance, or player-centered range
--     estimates when positions are unavailable. A unit counts only when its upper range bound is
--     within Distance. Uncertain positions, range, subgroup membership or required health/mana
--     values keep the whole condition unavailable, including under Unless. Percentage checks
--     require a positive maximum; empty aggregates have no result.
[3655] = "Usa posiciones legibles dentro de la misma instancia o, cuando no hay posiciones disponibles, estimaciones de alcance centradas en el jugador. Una unidad solo cuenta cuando el límite superior de su alcance está dentro de Distancia. Las posiciones, el alcance, la pertenencia a subgrupo o los valores de salud o maná necesarios inciertos dejan toda la condición sin disponibilidad, también bajo Salvo que. Las comprobaciones de porcentaje requieren un máximo positivo; los agregados vacíos no tienen resultado.",
-- 4953738e English: Count enemies when selected, or non-enemies when cleared.
[3656] = "Cuenta enemigos si está marcada, o no enemigos si no lo está.",
-- 5179228a English: The number of observed units proven within Distance of you.
[3657] = "El número de unidades observadas que se ha comprobado que están dentro de Distancia de ti.",
-- 5f3da9f5 English: Counts the addon's observed unit snapshot, including nameplates and tracked
--     unit aliases, rather than every nearby unit. A unit counts only when its upper range bound is
--     within Distance; uncertain membership or unreadable identity, hostility, range or nameplate
--     settings makes the whole count unavailable, including under Unless. Known vanished or reused
--     unit tokens are excluded. Distance cannot exceed the current nameplate distance setting; that
--     setting does not guarantee a complete scan.
[3658] = "Cuenta la instantánea de unidades observadas del addon, incluidas las placas de nombre y los alias de unidad rastreados, no todas las unidades cercanas. Una unidad solo cuenta cuando el límite superior de su alcance está dentro de Distancia; una pertenencia incierta o una identidad, hostilidad, alcance o ajuste de placas de nombre ilegibles dejan todo el recuento sin disponibilidad, también bajo Salvo que. Se excluyen los tokens de unidad que se sabe que han desaparecido o se han reutilizado. Distancia no puede superar el ajuste actual de distancia de las placas de nombre; ese ajuste no garantiza una exploración completa.",
-- 60bfbfa2 English: you {{!have|do not have}} {item} equipped
[3659] = "{{!tienes|no tienes}} {item} equipado",
-- 1d06a92b English: {item} {{!is|is not}} available{carrying}
[3660] = "{item} {{!está|no está}} disponible{carrying}",
-- ac058958 English: {item} {{!is|is not}} in range{carrying}
[3661] = "{item} {{!está|no está}} al alcance{carrying}",
-- 216e438b English: the cooldown on {item} {comparison} {duration}{carrying}
[3662] = "el tiempo de reutilización de {item} {comparison} {duration}{carrying}",
-- 623bd8c4 English: {unit} {{!is|is not}} in a group
[3663] = "{unit} {{!está|no está}} en un grupo",
-- fedfc418 English: {unit} {{!is friendly to you|is not friendly to you}}
[3664] = "{unit} {{!es amistoso contigo|no es amistoso contigo}}",
-- 6e21eee4 English: Matches when the selected unit is dead or a ghost. A missing or unreadable unit
--     is unavailable, including under NOT. In a Via Macro announcement, choose Announcement target
--     to follow the supplied unit.
[3665] = "Coincide cuando la unidad seleccionada está muerta o es un fantasma. Una unidad ausente o ilegible no está disponible, también bajo NO. En un anuncio Mediante macro, elige Objetivo del anuncio para seguir a la unidad proporcionada.",
-- eaa8232a English: Matches when the game reports the selected unit as friendly to you. This does
--     not imply party or raid membership. A missing or unreadable unit is unavailable.
[3666] = "Coincide cuando el juego indica que la unidad seleccionada es amistosa contigo. No implica pertenencia al grupo o a la banda. Una unidad ausente o ilegible no está disponible.",
-- b9151b16 English: Assisted Combat {{!is|is not}} suggesting a spell
[3667] = "El Asistente de combate {{!está|no está}} sugiriendo un hechizo",
-- 43bf497e English: Assisted Combat {{!suggests|does not suggest}} %s
-- %s #1: %s #1: a clickable spell link, e.g. "[Fireball]"
[3668] = "El Asistente de combate {{!sugiere|no sugiere}} %s",
-- 6c9594a9 English: Matches when Blizzard's Assisted Combat suggests this spell as the next cast.
--     An override counts as its base spell, and the base spell as its override. With no spell
--     chosen, matches whenever Assisted Combat suggests anything.
[3669] = "Se cumple cuando el Asistente de combate de Blizzard sugiere este hechizo como el siguiente que lanzar. Una sustitución cuenta como su hechizo base, y el hechizo base como su sustitución. Si no se elige ningún hechizo, se cumple siempre que el Asistente de combate sugiera algo.",
-- 44e850ce English: Assisted Combat exists on Retail (and is declared on Forever). Where the game
--     does not offer it, for this character or specialization, or the suggestion cannot be read,
--     this condition is unavailable rather than false, including under NOT.
[3670] = "El Asistente de combate existe en Retail (y está declarado en Forever). Donde el juego no lo ofrece, para este personaje o especialización, o no se puede leer la sugerencia, esta condición no está disponible en lugar de ser falsa, también bajo NOT.",
-- 32c737f7 English: %s {{!is|is not}} in Blizzard's Assisted Combat rotation
-- %s #1: %s #1: a clickable spell link, e.g. "[Fireball]"
[3671] = "%s {{!está|no está}} en la rotación del Asistente de combate de Blizzard",
-- ae726224 English: Matches when this spell is one Blizzard's Assisted Combat can suggest for your
--     current specialization. Its current override and its base spell count too. Use it to
--     highlight what Assisted Combat leaves out, for example a cooldown that is not in the set.
[3672] = "Se cumple cuando este hechizo es uno de los que el Asistente de combate de Blizzard puede sugerir para tu especialización actual. También cuentan su sustitución actual y su hechizo base. Úsala para resaltar lo que el Asistente de combate deja fuera, por ejemplo una reutilización que no está en el conjunto.",
-- 2a9b9d24 English: The set is read again whenever your spells change, never guessed. Where the
--     game does not offer Assisted Combat for this character or specialization, or the set cannot
--     be read, this condition is unavailable rather than false, including under NOT.
[3673] = "El conjunto se vuelve a leer cada vez que cambian tus hechizos, nunca se adivina. Si el juego no ofrece el Asistente de combate para este personaje o especialización, o no se puede leer el conjunto, esta condición no está disponible en lugar de ser falsa, también bajo NO.",
-- 10ac60e3 English: Assisted Combat {{!is|is not}} available
[3674] = "El Asistente de combate {{!está|no está}} disponible",
-- d882c8a9 English: Matches when the game offers Blizzard's Assisted Combat for your character and
--     current specialization. When it does not (for example a specialization Blizzard has no
--     Assisted Combat rotation for, or a client that declares the API but does not offer the
--     feature), this is false, so a branch can fall back to your own steps.
[3675] = "Se cumple cuando el juego ofrece el Asistente de combate de Blizzard para tu personaje y tu especialización actual. Cuando no lo hace (por ejemplo, una especialización para la que Blizzard no tiene rotación del Asistente de combate, o un cliente que declara la API pero no ofrece la función), es falsa, de modo que una rama puede recurrir a tus propios pasos.",
-- 65331c0d English: Unavailable only where the client has no Assisted Combat API or its answer
--     cannot be read, including under NOT.
[3676] = "No está disponible solo cuando el cliente no tiene la API del Asistente de combate o no se puede leer su respuesta, también bajo NO.",
